import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"Blockübersicht","description":"Die drei Blockgruppen in ApptiveGrid-Seiten und wann Sie welche brauchen.","frontmatter":{"title":"Blockübersicht","description":"Die drei Blockgruppen in ApptiveGrid-Seiten und wann Sie welche brauchen."},"headers":[],"relativePath":"seiten/bloecke.md","filePath":"seiten/bloecke.md","lastUpdated":1786024399000}'),i={name:"seiten/bloecke.md"};function l(s,e,o,d,h,c){return n(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="blockubersicht" tabindex="-1">Blockübersicht <a class="header-anchor" href="#blockubersicht" aria-label="Permalink to &quot;Blockübersicht&quot;">​</a></h1><p>Blöcke sind die Bausteine einer Seite. Diese Seite ordnet sie ein — die vollständige Liste mit allen Einstellungen steht in der <a href="/referenz/blocktypen">Blocktypen-Referenz</a>.</p><h2 id="die-drei-gruppen" tabindex="-1">Die drei Gruppen <a class="header-anchor" href="#die-drei-gruppen" aria-label="Permalink to &quot;Die drei Gruppen&quot;">​</a></h2><p>Die Blockauswahl ist gegliedert in:</p><table tabindex="0"><thead><tr><th>Gruppe</th><th>Wofür</th></tr></thead><tbody><tr><td><strong>Basis-Blöcke</strong></td><td>Text, Überschriften, Bilder, Unterseiten, Layout</td></tr><tr><td><strong>Spezial-Blöcke</strong></td><td>Daten anzeigen, auswerten, einbetten, verknüpfen</td></tr><tr><td><strong>Formularfeld-Blöcke</strong></td><td>Daten erfassen</td></tr></tbody></table><h2 id="basis-blocke" tabindex="-1">Basis-Blöcke <a class="header-anchor" href="#basis-blocke" aria-label="Permalink to &quot;Basis-Blöcke&quot;">​</a></h2><p>Der Grundstock jeder Seite: <strong>Absatz</strong>, <strong>Überschrift 1</strong> bis <strong>3</strong>, <strong>Bild</strong>, <strong>Seite</strong> (Unterseite) und die vier Layout-Blöcke.</p><p>Damit bauen Sie Dokumentation, Handbücher und Notizen — und mit den Layouts die Struktur für alles Weitere.</p><p>→ <a href="/seiten/layout-bloecke">Layout-Blöcke</a></p><h2 id="spezial-blocke" tabindex="-1">Spezial-Blöcke <a class="header-anchor" href="#spezial-blocke" aria-label="Permalink to &quot;Spezial-Blöcke&quot;">​</a></h2><p>Hier liegt der eigentliche Unterschied zu einem Textdokument.</p><h3 id="daten-anzeigen" tabindex="-1">Daten anzeigen <a class="header-anchor" href="#daten-anzeigen" aria-label="Permalink to &quot;Daten anzeigen&quot;">​</a></h3><ul><li><strong>Grid Ansicht</strong> — bettet eine bestehende Ansicht ein. Der wichtigste Block für Portale.</li><li><strong>Grid Liste</strong> — erzeugt aus Einträgen eine frei gestaltete Liste.</li><li><strong>Dateiliste</strong> — Listenansicht mit Drag-&amp;-Drop-Upload.</li></ul><h3 id="auswerten" tabindex="-1">Auswerten <a class="header-anchor" href="#auswerten" aria-label="Permalink to &quot;Auswerten&quot;">​</a></h3><ul><li><strong>Zähler</strong> — Anzahl der Einträge einer Ansicht</li><li><strong>Summenkarte</strong> — Summe einer numerischen Spalte</li><li><strong>Donut-Diagramm</strong> — Verteilung über eine Einzelauswahl-Spalte</li></ul><div class="tip custom-block"><p class="custom-block-title">Ein Dashboard in fünf Minuten</p><p>Drei bis vier Auswertungsblöcke in einem horizontalen Layout ergeben eine Kennzahlenzeile. Darunter eine eingebettete Grid-Ansicht mit den Details — mehr braucht ein brauchbares Dashboard meist nicht.</p></div><h3 id="aktionen-auslosen" tabindex="-1">Aktionen auslösen <a class="header-anchor" href="#aktionen-auslosen" aria-label="Permalink to &quot;Aktionen auslösen&quot;">​</a></h3><ul><li><strong>Button</strong> — startet ein Formular oder einen Flow</li><li><strong>QR Code</strong> — dasselbe als QR-Code, für Aushänge und Druck</li><li><strong>Flow</strong> — bindet einen Flow ein</li></ul><h3 id="externes-einbinden" tabindex="-1">Externes einbinden <a class="header-anchor" href="#externes-einbinden" aria-label="Permalink to &quot;Externes einbinden&quot;">​</a></h3><ul><li><strong>Einbinden</strong> — beliebige externe Inhalte per iframe</li><li><strong>HTML</strong> — eigener Code, auf Wunsch per KI erzeugt</li></ul><h2 id="formularfeld-blocke" tabindex="-1">Formularfeld-Blöcke <a class="header-anchor" href="#formularfeld-blocke" aria-label="Permalink to &quot;Formularfeld-Blöcke&quot;">​</a></h2><p>Alle Eingabefelder, die Sie aus <a href="/formulare/felder-konfigurieren">Formularen</a> kennen — hier aber frei platzierbar, kombinierbar mit Text und Layout und mit <a href="/seiten/sichtbarkeit">bedingter Sichtbarkeit</a>.</p><p>Grob nach Zweck:</p><table tabindex="0"><thead><tr><th>Zweck</th><th>Blöcke</th></tr></thead><tbody><tr><td>Text</td><td>Einzeiliges Textfeld, Mehrzeiliges Textfeld</td></tr><tr><td>Zahlen</td><td>Zahl, Kommazahl, Währung, Bewertungsskala</td></tr><tr><td>Auswahl</td><td>Auswahl als Dropdown, Auswahl als Liste, Mehrfachauswahl, Häkchen, Entscheidung</td></tr><tr><td>Zeit</td><td>Datum, Datum und Uhrzeit</td></tr><tr><td>Kontakt</td><td>E-Mail, Telefon, URL, Anschrift</td></tr><tr><td>Ort</td><td>Standort</td></tr><tr><td>Verknüpfung</td><td>Eintrag, Einträge</td></tr><tr><td>Medien</td><td>Dateien oder Fotos hochladen, Foto Kamera, Video, Video hochladen, Sprachaufnahme</td></tr><tr><td>Sonstiges</td><td>Unterschrift, Barcode-Scanner, HTML mit Formularfeldern</td></tr></tbody></table><h2 id="welcher-block-fur-welche-aufgabe" tabindex="-1">Welcher Block für welche Aufgabe <a class="header-anchor" href="#welcher-block-fur-welche-aufgabe" aria-label="Permalink to &quot;Welcher Block für welche Aufgabe&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sie wollen …</th><th>Block</th></tr></thead><tbody><tr><td>Eine Tabelle im Portal zeigen</td><td><strong>Grid Ansicht</strong></td></tr><tr><td>Eine Kennzahl hervorheben</td><td><strong>Zähler</strong> oder <strong>Summenkarte</strong></td></tr><tr><td>Eine Verteilung zeigen</td><td><strong>Donut-Diagramm</strong></td></tr><tr><td>Einen Prozess starten lassen</td><td><strong>Button</strong></td></tr><tr><td>Etwas am Aushang scannbar machen</td><td><strong>QR Code</strong></td></tr><tr><td>Dateien einsammeln</td><td><strong>Dateiliste</strong> oder <strong>Dateien oder Fotos hochladen</strong></td></tr><tr><td>Inhalte je Eintrag wiederholen</td><td><strong>Grid Liste</strong></td></tr><tr><td>Etwas Externes zeigen</td><td><strong>Einbinden</strong></td></tr><tr><td>Volle gestalterische Freiheit</td><td><strong>HTML</strong></td></tr><tr><td>Mehrere Bereiche auf einer Seite</td><td><strong>Tab-Layout</strong></td></tr><tr><td>Einen geführten Ablauf</td><td><strong>Stepper-Layout</strong></td></tr></tbody></table><h2 id="blocke-verschachteln" tabindex="-1">Blöcke verschachteln <a class="header-anchor" href="#blocke-verschachteln" aria-label="Permalink to &quot;Blöcke verschachteln&quot;">​</a></h2><p>Layout-Blöcke enthalten andere Blöcke. Zwei Kennzahlen nebeneinander und darunter eine Tabelle bauen Sie so:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vertikales Layout</span></span>
<span class="line"><span>├── Horizontales Layout</span></span>
<span class="line"><span>│   ├── Zähler</span></span>
<span class="line"><span>│   └── Summenkarte</span></span>
<span class="line"><span>└── Grid Ansicht</span></span></code></pre></div><p>Ab dieser Verschachtelungstiefe sollten Sie im <a href="/seiten/seite-erstellen">Strukturmodus</a> arbeiten — im normalen Editor ist schwer zu erkennen, welcher Block in welchem liegt.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/referenz/blocktypen">Blocktypen-Referenz</a></li><li><a href="/seiten/layout-bloecke">Layout-Blöcke</a></li><li><a href="/seiten/auswertungen">Ansichten und Auswertungen einbetten</a></li><li><a href="/seiten/sichtbarkeit">Bedingte Sichtbarkeit</a></li></ul>`,32)])])}const g=t(i,[["render",l]]);export{b as __pageData,g as default};
